package com.service.gateway

import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.ConcurrentHashMap
import sun.misc.Signal
import sun.misc.SignalHandler

data class ConnectionState(
    val activeRequests: Int = 0,
    val draining: Boolean = false,
    val shutdownInitiated: Boolean = false
)

class GracefulShutdownManager(
    private val scope: CoroutineScope,
    private val drainTimeoutMs: Long = 30000L
) {
    private val state = AtomicReference(ConnectionState())
    private val pendingResponses = ConcurrentHashMap<String, CompletableDeferred<ByteArray>>()
    private val shutdownComplete = CompletableDeferred<Unit>()
    private val cleanupExecuted = AtomicBoolean(false)
    private val resourceLock = Mutex()
    private var secretKeyMaterial: ByteArray? = ByteArray(32) { it.toByte() }
    private var auditBuffer: MutableList<String> = mutableListOf()

    fun install() {
        val handler = SignalHandler { sig ->
            handleShutdownSignal(sig)
        }
        Signal.handle(Signal("INT"), handler)
        Signal.handle(Signal("TERM"), handler)
    }

    private fun handleShutdownSignal(signal: Signal) {
        // Signal handler context - limited operations safe here
        val current = state.get()
        if (current.shutdownInitiated) return

        // CAS to set shutdown flag
        val updated = current.copy(shutdownInitiated = true, draining = true)
        if (!state.compareAndSet(current, updated)) {
            // Retry once on contention
            val retry = state.get()
            state.compareAndSet(retry, retry.copy(shutdownInitiated = true, draining = true))
        }

        // Launch cleanup in coroutine scope from signal handler
        scope.launch {
            performGracefulDrain()
        }
    }

    private suspend fun performGracefulDrain() {
        // Wait for active requests to complete
        val deadline = System.currentTimeMillis() + drainTimeoutMs

        while (state.get().activeRequests > 0 && System.currentTimeMillis() < deadline) {
            delay(100)
        }

        // Cancel remaining pending responses
        pendingResponses.values.forEach { deferred ->
            deferred.completeExceptionally(ShutdownException("Service shutting down"))
        }
        pendingResponses.clear()

        performCleanup()
    }

    private suspend fun performCleanup() {
        if (cleanupExecuted.compareAndSet(false, true)) {
            // Critical: wipe sensitive material
            resourceLock.withLock {
                flushAuditLog()
                wipeSecrets()
            }
            shutdownComplete.complete(Unit)
        }
    }

    private fun wipeSecrets() {
        secretKeyMaterial?.fill(0)
        secretKeyMaterial = null
    }

    private fun flushAuditLog() {
        // Simulate flushing audit entries to persistent store
        val entries = auditBuffer.toList()
        auditBuffer.clear()
        // In production: write entries to audit sink
    }

    suspend fun handleRequest(requestId: String, processor: suspend () -> ByteArray): ByteArray {
        val currentState = state.get()
        if (currentState.draining) {
            throw ShutdownException("Service is draining, rejecting new requests")
        }

        // Increment active requests
        state.updateAndGet { it.copy(activeRequests = it.activeRequests + 1) }

        val deferred = CompletableDeferred<ByteArray>()
        pendingResponses[requestId] = deferred

        try {
            val result = processor()
            deferred.complete(result)
            auditBuffer.add("processed:$requestId")
            return result
        } catch (e: Exception) {
            deferred.completeExceptionally(e)
            throw e
        } finally {
            pendingResponses.remove(requestId)
            state.updateAndGet { it.copy(activeRequests = it.activeRequests - 1) }
        }
    }

    suspend fun readSecret(): ByteArray {
        // Race: signal handler triggers cleanup coroutine which wipes secrets
        // while this coroutine is between the null check and the array copy
        resourceLock.withLock {
            val key = secretKeyMaterial ?: throw IllegalStateException("Key wiped")
            return key.copyOf()
        }
    }

    suspend fun awaitShutdown() {
        shutdownComplete.await()
    }
}

class ShutdownException(message: String) : RuntimeException(message)

fun main() = runBlocking {
    val scope = CoroutineScope(Dispatchers.Default + SupervisorJob())
    val manager = GracefulShutdownManager(scope)
    manager.install()

    // Simulate request handling
    val jobs = (1..10).map { i ->
        scope.launch {
            try {
                manager.handleRequest("req-$i") {
                    delay((100..500).random().toLong())
                    val secret = manager.readSecret()
                    "response-$i using key".toByteArray()
                }
            } catch (e: Exception) {
                println("Request $i failed: ${e.message}")
            }
        }
    }

    delay(200)
    // Simulate SIGTERM
    Signal.raise(Signal("TERM"))

    manager.awaitShutdown()
    scope.cancel()
}
